
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_revtpssh_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_revtpssh", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.359617085614635e+00, -4.271873000818015e+00, -4.148824782110831e+00, -3.978170450215618e+00, -3.745218032735036e+00, -3.434349484063728e+00, -3.032709151165883e+00, -2.537529528729114e+00, -1.969432567328355e+00, -1.393769861440780e+00, -9.084047883589244e-01, -6.583016793330562e-01, -5.860550031454675e-01, -4.906740648440332e-01, -3.449238873615041e-01, -2.064461657632780e-01, -1.130734363563634e-01, -4.411744170489578e-02, -9.725858175949651e-03, -1.094574828162717e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


